        function formatListTime(dateStr) {
            if (!dateStr) return '';
            try {
                var d = new Date(dateStr);
                var tz = (vm.airfield && vm.airfield.timezone) ? vm.airfield.timezone : undefined;
                return d.toLocaleTimeString('en-GB', {
                    hour: '2-digit',
                    minute: '2-digit',
                    timeZone: tz
                });
            } catch (e) {
                return dateStr;
            }
        }
