    vm.club_id = vm.user && vm.user.current_club_admin ? vm.user.current_club_admin.id : null;
    vm.is_super_admin = !!(vm.user && vm.user.access && vm.user.access.super_admin && vm.user.access.super_admin.indexOf(vm.club_id) > -1);

