    ScheduleDisplayController.$inject = ['ScheduleDisplayService', '$scope', '$stateParams', '$interval', '$timeout'];
    function ScheduleDisplayController(ScheduleDisplayService, $scope, $stateParams, $interval, $timeout) {
        var vm = this;

        // ── State ──
        vm.token = $stateParams.token;
        vm.club_name = '';
        vm.loading = true;
        vm.error = false;
        vm.error_message = '';
        vm.revoked = false;
        vm.current_time = '';
        vm.connected = true;
        vm.today_label = '';

        var currentVersion = -1;
        var pollTimer = null;
        var clockTimer = null;

        // ── Initialise ──
        init();

        function init() {
            if (!vm.token) {
                vm.loading = false;
                vm.error = true;
                vm.error_message = 'No display token provided. Please check the URL.';
                return;
            }

            // Start the clock
            updateClock();
            clockTimer = $interval(updateClock, 1000);

            // Fetch club info
            ScheduleDisplayService.GetClubInfo(vm.token)
                .then(function(data) {
                    if (data.success) {
                        // Backend returns { club: { id, title } }
                        vm.club_name = (data.club && data.club.title) ? data.club.title : (data.club_name || data.name || '');
                        vm.loading = false;
                        // Calendar will be initialised from the view's inline script
                        // once it detects vm.loading === false
                    } else {
                        vm.loading = false;
                        vm.error = true;
                        vm.error_message = 'Invalid or expired display token. Please ask your club manager to generate a new link.';
                    }
                }, function() {
                    vm.loading = false;
                    vm.error = true;
                    vm.error_message = 'Could not connect to the server. Please check your internet connection.';
                });
        }

        // ── Clock ──
        function updateClock() {
            var now = new Date();
            var hours = String(now.getHours()).padStart(2, '0');
            var mins  = String(now.getMinutes()).padStart(2, '0');
            var secs  = String(now.getSeconds()).padStart(2, '0');
            vm.current_time = hours + ':' + mins + ':' + secs;

            var days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
            var months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
            vm.today_label = days[now.getDay()] + ' ' + now.getDate() + ' ' + months[now.getMonth()] + ' ' + now.getFullYear();
        }

        // ── Load schedule data (called from view) ──
        $scope.loadSchedule = function(start, end) {
            return ScheduleDisplayService.GetSchedule(vm.token, start, end)
                .then(function(data) {
                    if (data.success !== false && data.resources) {
                        currentVersion = data.schedule_version;
                        vm.connected = true;

                        // Filter out waiting list resources (waiting == 1)
                        data.resources = data.resources.filter(function(r) {
                            return r.waiting != 1;
                        });

                        // Also filter out events assigned to waiting list resources
                        data.events = data.events.filter(function(e) {
                            return !e.waiting_list || e.waiting_list == 0;
                        });

                        return data;
                    } else {
                        if (data.message && data.message.toLowerCase().indexOf('revok') > -1) {
                            vm.revoked = true;
                        }
                        return null;
                    }
                }, function() {
                    vm.connected = false;
                    return null;
                });
        };

        // ── Start polling ──
        $scope.startPolling = function() {
            if (pollTimer) return;

            pollTimer = $interval(function() {
                ScheduleDisplayService.GetVersion(vm.token)
                    .then(function(data) {
                        vm.connected = true;

                        if (!data.success) {
                            // Token was revoked
                            vm.revoked = true;
                            $interval.cancel(pollTimer);
                            pollTimer = null;
                            return;
                        }

                        if (data.schedule_version !== currentVersion) {
                            // Something changed — trigger reload from view
                            $scope.$broadcast('schedule:version-changed');
                        }
                    }, function() {
                        // Network error — will retry next poll
                        vm.connected = false;
                    });
            }, 30000); // 30 seconds
        };

        // ── Schedule midnight rollover ──
        $scope.scheduleMidnightRollover = function() {
            var now = new Date();
            var tomorrow = new Date(now);
            tomorrow.setDate(tomorrow.getDate() + 1);
            tomorrow.setHours(0, 0, 5, 0); // 5 seconds past midnight

            var msUntilMidnight = tomorrow.getTime() - now.getTime();

            $timeout(function() {
                $scope.$broadcast('schedule:midnight-rollover');
                $scope.scheduleMidnightRollover(); // schedule next
            }, msUntilMidnight);
        };

        // ── Cleanup ──
        $scope.$on('$destroy', function() {
            if (pollTimer) { $interval.cancel(pollTimer); }
            if (clockTimer) { $interval.cancel(clockTimer); }
        });
    }

// ─────────────────────────────────────────────────────
// ShareAssignmentModalController — instructor shares a questionnaire/material
// with one or more students (message + optional due date). Used via $uibModal.
// Resolves: clubId, item ({type, id, title}), context ({attach_type, attach_id,
// timing, course_sitting_id, course_id}).
// ─────────────────────────────────────────────────────
app.controller('ShareAssignmentModalController', ShareAssignmentModalController);

    ShareAssignmentModalController.$inject = ['$uibModalInstance', 'CourseAssignmentService', 'MemberService', 'ToastService', '$q', 'clubId', 'item', 'context'];
    function ShareAssignmentModalController($uibModalInstance, CourseAssignmentService, MemberService, ToastService, $q, clubId, item, context) {
        var m = this;
        m.item = item;                 // { type, id, title }
        m.context = context || {};
        m.loadingStudents = true;
        m.students = [];               // all club members
        m.selected = [];               // chosen students
        m.message = '';
        m.dueDate = null;
        m.sendEmail = true;

        (MemberService.GetAllByClub ? MemberService.GetAllByClub(clubId) : $q.when([])).then(function(data) {
            m.loadingStudents = false;
            var members = (data && data.members) ? data.members : (angular.isArray(data) ? data : []);
            m.students = members.map(function(mem) {
                return { id: mem.user_id || mem.id, name: ((mem.first_name || '') + ' ' + (mem.last_name || '')).trim(), email: mem.email || '' };
            }).filter(function(s) { return s.id; });
        });

        // ui-select multiple gives us m.selected directly; keep a removeable chip list.
        m.removeStudent = function(s) {
            m.selected = m.selected.filter(function(x) { return x.id !== s.id; });
        };

        function ymd(d) {
            if (!d) return null;
            if (typeof d === 'string') return d.slice(0, 10);
            var y = d.getFullYear(), mo = ('0' + (d.getMonth() + 1)).slice(-2), da = ('0' + d.getDate()).slice(-2);
            return y + '-' + mo + '-' + da;
        }

        m.share = function() {
            if (!m.selected.length) { ToastService.warning('Pick a student', 'Choose at least one student to share with.'); return; }
            var payload = {
                item_type: m.item.type,
                item_id: m.item.id,
                student_ids: m.selected.map(function(s) { return s.id; }),
                message: m.message || '',
                due_date: ymd(m.dueDate),
                send_email: m.sendEmail ? true : false
            };
            // Carry the course/lesson context so the deep link + attempt bind correctly.
            ['attach_type', 'attach_id', 'timing', 'course_sitting_id', 'course_id'].forEach(function(k) {
                if (m.context[k] != null && m.context[k] !== '') payload[k] = m.context[k];
            });
            submit(payload, false);
        };

        // ── Re-assign confirmation ──
        // The backend returns needs_confirm:true (NOT an error) when a student in
        // results[] has already_completed:true. We surface its message and, on
        // confirm, re-POST the identical payload with confirm:true — which re-assigns
        // and grants a fresh blank attempt (the old one is preserved). confirm:true
        // is idempotent-friendly, so re-sending all students is safe.
        m.confirmNeeded = false;
        m.confirmMessage = '';
        var pendingPayload = null;

        function submit(payload, confirmed) {
            m.sharing = true;
            if (confirmed) payload.confirm = true;
            CourseAssignmentService.Share(payload).then(function(data) {
                m.sharing = false;

                if (data && data.needs_confirm && !confirmed) {
                    // Not an error — ask the instructor, then retry with confirm:true.
                    pendingPayload = payload;
                    m.confirmMessage = data.message ||
                        'One or more students have already completed this. Re-assign anyway? A fresh retake will be granted.';
                    m.confirmNeeded = true;
                    return;
                }

                m.confirmNeeded = false;
                if (!data || data.success === false) { ToastService.error('Could not share', (data && data.message) || ''); return; }
                var shared = data.shared || (data.results ? data.results.length : m.selected.length);
                var emailed = (data.results || []).filter(function(r) { return r.emailed; }).length;
                ToastService.success('Shared with ' + shared + ' student' + (shared === 1 ? '' : 's'),
                    m.sendEmail ? (emailed + ' notified by email.') : 'Added to their tasks (no email).');
                $uibModalInstance.close(data);
            });
        }

        m.confirmReassign = function() {
            if (!pendingPayload) return;
            submit(pendingPayload, true);
        };
        m.cancelReassign = function() {
            m.confirmNeeded = false;
            pendingPayload = null;
        };

        m.cancel = function() { $uibModalInstance.dismiss('cancel'); };
    }

